verus! {

    /// Given a reference to a vector `a` of arbitrary element type `T`,
    /// returns a new `Vec<i32>` of the same length, filled with 1’s.
    fn ones_like<T>(a: &Vec<T>) -> Vec<i32>
        // no preconditions needed other than `a` being a valid vector
        ensures
            // (1) output length equals input length
            result.len() == a.len(),
        ensures
            // (2) every element of the output is 1
            forall |i: usize| i < a.len() ==> result[i] == 1,
    {
        // Allocate an empty result vector with capacity for a.len() elements
        let mut result: Vec<i32> = Vec::with_capacity(a.len());
        let mut i: usize = 0;

        // Loop from i = 0 up to i == a.len()
        while i < a.len() {
            // Invariant 1: loop counter stays within [0, a.len()]
            invariant i <= a.len();
            // Invariant 2: result.len() tracks the number of iterations done
            invariant result.len() == i;
            // Invariant 3: all written elements so far are 1
            invariant forall |j: usize| j < i ==> result[j] == 1;
            // Termination metric: the remaining number of iterations
            decreases a.len() - i;

            // Body: append a 1
            result.push(1);

            // Supporting assertions to help the verifier
            assert(result.len() == i + 1);        // one more element
            assert(result[i] == 1);               // just-pushed element is 1

            i += 1;
        }

        // Final check (redundant w.r.t. ensures, but good for clarity)
        assert(result.len() == a.len());
        result
    }

}